# coding=utf-8
from abc import ABCMeta, abstractmethod
from contextlib import contextmanager

from six import add_metaclass

from hran_pacman.bases.logger import LOGGER
from hran_pacman.package_validation import retry_when_file_is_corrupted
from hran_pacman.storages import LocalStorage, RemoteStorage, TemporaryStorage


@add_metaclass(ABCMeta)
class DownloaderBase(object):
    """
    Base abstract class for every future downloader.

    Provides basic
    functionality of package download management.

    Serves as an future
    contract of providing interface which includes methods:

        - get_software_package
        - get_site_manager
    """

    technology = ""

    def __init__(
        self,
        baseline,
        api_key=None,
        local_storage=LocalStorage,
        remote_storage=RemoteStorage,
        temporary_storage=TemporaryStorage,
        turbo_mode=False,
    ):
        self.baseline = baseline
        self.api_key = api_key
        if self.technology is None:
            raise ValueError("Technology cannot be None")
        self.temporary_storage = temporary_storage
        self.local_storage_class = local_storage
        self.remote_storage_class = remote_storage
        self.fast_download = turbo_mode

    @property
    def remote_storage(self):
        return self.remote_storage_class(**self._storage_data) if self.remote_storage_class else None

    @property
    def local_storage(self):
        return self.local_storage_class(**self._storage_data) if self.local_storage_class else None

    @property
    def temporary_container(self):
        return self.temporary_storage(**self._storage_data) if self.temporary_storage else None

    @property
    def _storage_data(self):
        return {"baseline": self.baseline, "package_name": self.downloaded_name}

    @property
    def package_name(self):
        return None

    @property
    def downloaded_name(self):
        return self.package_name


    def get_package(self):
        """
        Start package downloading process based on decision tree:

        ..                      is turbo mode active?
        ..                              -|------------------------------------
        ..                            no |                                   |
        ..                               |                               yes |
        ..                  is package available locally?                    |
        ..           --------------------|--------------------               |
        ..           |                                       |               |
        ..       yes |                                       | no            |
        ..           |                                       |               |
        ..   inform that package             is package available remotely?  |
        ..   is available locally               -------------|--------       |
        ..                                      |                    |       |
        ..                                  yes |                    |--------
        ..                                      |                    |
        ..                           copy package from remote        | no
        ..                                                           |
        ..                                                           |
        ..                                    download package from repository

        .. blockdiag::
           :scale: 100%

            blockdiag {
               node_width = 250;

               F [label = "is turbo mode active?"];
               A [label = "is package available locally?"];
               B [label = "inform that package is available locally"];
               C [label = "is package available remotely?"];
               D [label = "copy package from remote"];
               E [label = "download package from repository"];

               F -> E [label = "yes", textcolor="green"];
               F -> A [label = "not", textcolor="red"];
               A -> B [label = "yes", textcolor="green"];
               A -> C [label = "not", textcolor="red"];
               C -> D [label = "yes", textcolor="green"];
               C -> E [label = "not", textcolor="red"];
            }
        """

        LOGGER.info("Starting package and tools download for baseline {}.".format(self.baseline))
        if self.fast_download:
            self.download_package_from_repository_without_further_distribution()
        else:
            self._get_package_according_to_descision_tree()

    def _get_package_according_to_descision_tree(self):
        if self.package_is_available_locally():
            self.inform_that_package_is_available_locally()
        elif self.package_is_available_remotely():
            try:
                self.get_package_from_remote()
            except IOError as e:
                LOGGER.info('Package cannot be obtained from remote')
                LOGGER.debug('Exception has been triggered {}: {}'.format(e.__class__, e.__doc__))
                self.download_package_from_repository()
        else:
            self.download_package_from_repository()

    def package_is_available_locally(self):
        local_storage_exists = self.local_storage
        package_is_on_local = self.local_storage.specific_package_available()
        return local_storage_exists and package_is_on_local

    def package_is_available_remotely(self):
        remote_storage_exists = self.remote_storage
        if not remote_storage_exists:
            return remote_storage_exists
        package_is_on_remote = self.remote_storage.specific_package_available()
        return remote_storage_exists and package_is_on_remote

    def inform_that_package_is_available_locally(self):
        LOGGER.info("Requested package is already available at {}".format(self.local_storage.package_path))

    def get_package_from_remote(self):
        LOGGER.info(
            "Requested package is available at remote: "
            "{}, downloading from there".format(self.remote_storage.package_path)
        )
        copy_from_with_validation = retry_when_file_is_corrupted(self._copy_on_local, self.remote_storage.package_path)

        copy_from_with_validation(self.remote_storage)

    def download_package_from_repository(self):
        LOGGER.info("Package isn't avaliable locally or remotely, downloading from repository")
        with self._lock_remote():
            with self.temporary_container.prepare_environment():
                status = self._download_package_to_temporary_container()
                if status:
                    self._delegate_package_from_tmp_into_destination_places()

    def download_package_from_repository_without_further_distribution(self):
        with self.temporary_container.prepare_environment():
            status = self._download_package_to_temporary_container()
            if status:
                self._copy_on_local(self.temporary_container)

    @contextmanager
    def _lock_remote(self):
        self.remote_storage and self.remote_storage.lock.acquire("Downloading...")
        try:
            yield
        finally:
            self.remote_storage and self.remote_storage.lock.unlock()

    def _download_package_to_temporary_container(self):
        download_with_validation = retry_when_file_is_corrupted(
            self.download_files, self.temporary_container.package_path
        )
        downloading_status = download_with_validation()
        return downloading_status

    def download_files(self):
        self.get_software_package()
        self.get_site_manager()

    def _delegate_package_from_tmp_into_destination_places(self):
        self._copy_on_remote_with_validation()
        self._copy_on_local_with_validation()

    def _copy_on_local_with_validation(self):
        self._decorate_with_validator(self._copy_on_local, package_path=self.temporary_container.package_path)(
            self.temporary_container
        )

    def _copy_on_remote_with_validation(self):
        self._decorate_with_validator(self._copy_on_remote, package_path=self.temporary_container.package_path)(
            self.temporary_container
        )

    def _decorate_with_validator(self, func, package_path):
        copy_on_local_with_validation = retry_when_file_is_corrupted(func, package_path=package_path)
        return copy_on_local_with_validation

    def _copy_on_local(self, source):
        self.local_storage and self.local_storage.copy_content_from(source)

    def _copy_on_remote(self, source):
        try:
            self.remote_storage and self.remote_storage.copy_content_from(source)
        except Exception:
            LOGGER.exception("Error occurred during copying package into remote storage, operation omitted")

    @abstractmethod
    def get_software_package(self):
        """
        Hook for software package download implementation
        """

    @abstractmethod
    def get_site_manager(self):
        """
        Hook for BTS Site Manager package download implementation
        """
